const LANG_HTML_CODE = { IT: "it", EN: "en", FR: "fr", DE: "de", SP: "es", RU: "ru", AR: "ar", CH: "zh", JP: "ja" };

function applyLanguage(code) {
  const dict = I18N[code] || I18N.EN;
  document.documentElement.lang = LANG_HTML_CODE[code] || "en";
  document.documentElement.dir = code === "AR" ? "rtl" : "ltr";

  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const value = dict[el.dataset.i18n];
    if (value === undefined) return;
    if (el.classList.contains("vs-word")) {
      /* Typewriter-mode headings type from data-full-text rather than
         textContent, so update that cache; only touch textContent live
         if the word has already finished typing (i.e. isn't blank). */
      el.dataset.fullText = value;
      if (el.textContent !== "") el.textContent = value;
    } else {
      el.textContent = value;
    }
  });

  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const value = dict[el.dataset.i18nPlaceholder];
    if (value !== undefined) el.setAttribute("placeholder", value);
  });

  document.querySelectorAll("[data-i18n-aria]").forEach((el) => {
    const value = dict[el.dataset.i18nAria];
    if (value !== undefined) el.setAttribute("aria-label", value);
  });

  try { localStorage.setItem("codutti_lang", code); } catch (e) {}
}
window.applyLanguage = applyLanguage;
